// Cuts per-request overhead: connection reuse, hybrid rate limit, async log, coalescing.
package com.bank.gateway.demo;

import java.util.concurrent.*;
import java.util.logging.*;

public class OverheadDemo {
    private static final Logger log = Logger.getLogger("Overhead");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new OvLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        OptimizedGateway gateway = new OptimizedGateway();
        int requests = 200;

        log.info("=== Steady traffic: connection reuse + hybrid rate limit + async log ===");
        for (int i = 0; i < requests; i++) gateway.handle("SAV2001");

        log.info("=== Burst: 50 identical in-flight lookups → coalesced to 1 call ===");
        ExecutorService pool = Executors.newFixedThreadPool(16);
        CountDownLatch latch = new CountDownLatch(50);
        for (int i = 0; i < 50; i++) pool.submit(() -> { gateway.coalescedLookup("HOT-ACCOUNT"); latch.countDown(); });
        latch.await();
        pool.shutdown();

        gateway.report();
    }
}

