class ConnectionPool {
    private int open = 0; private int reuses = 0; private int newHandshakes = 0;
    private final int maxConnections;
    ConnectionPool(int maxConnections) { this.maxConnections = maxConnections; }
    // Reuse an existing connection when available; only handshake when pool must grow.
    void acquire() {
        if (open > 0 && open <= maxConnections) { reuses++; }      // HTTP/2 multiplex / keep-alive reuse
        else { newHandshakes++; open = Math.min(open + 1, maxConnections); } // TCP+TLS handshake
    }
    double reusePercent() {
        int total = reuses + newHandshakes;
        return total == 0 ? 0 : (reuses * 100.0 / total);
    }
    int getNewHandshakes() { return newHandshakes; }
}

