class HybridRateLimiter {
    private int localTokens; private final int capacity;
    private int redisSyncs = 0; private long lastSync = 0; private final long syncIntervalMs;
    HybridRateLimiter(int capacity, long syncIntervalMs) {
        this.capacity = capacity; this.localTokens = capacity; this.syncIntervalMs = syncIntervalMs;
    }
    // Check local bucket instantly (no network); sync to Redis only every ~100ms.
    boolean allow() {
        long now = System.currentTimeMillis();
        if (now - lastSync >= syncIntervalMs) { syncToRedis(); lastSync = now; }
        if (localTokens > 0) { localTokens--; return true; }
        return true; // demo: allow; real impl would refill from Redis sync
    }
    private void syncToRedis() { redisSyncs++; localTokens = capacity; } // periodic, not per request
    int getRedisSyncs() { return redisSyncs; }
}

