class AsyncBatchLogger {
    private static final Logger log = Logger.getLogger("Overhead");
    private final BlockingQueue<String> q = new LinkedBlockingQueue<>();
    private final ExecutorService worker = Executors.newSingleThreadExecutor();
    private volatile boolean running = true; private int batchesFlushed = 0;
    AsyncBatchLogger() {
        worker.submit(() -> {
            java.util.List<String> batch = new java.util.ArrayList<>();
            while (running || !q.isEmpty()) {
                String item = q.poll();
                if (item != null) batch.add(item);
                if (batch.size() >= 50) { batchesFlushed++; batch.clear(); }
            }
        });
    }
    void log(String msg) { q.offer(msg); } // instant enqueue, request never waits
    int getBatchesFlushed() { return batchesFlushed; }
    void shutdown() { running = false; worker.shutdown(); }
}

