class RequestCoalescer {
    private int downstreamCalls = 0; private int coalesced = 0;
    private final ConcurrentHashMap<String, CompletableFuture<String>> inFlight = new ConcurrentHashMap<>();
    // single-flight: identical concurrent requests share ONE downstream call.
    String lookup(String key, java.util.function.Function<String,String> downstream) {
        CompletableFuture<String> existing = inFlight.get(key);
        if (existing != null) { coalesced++; return existing.join(); }   // join the in-flight call
        CompletableFuture<String> f = new CompletableFuture<>();
        if (inFlight.putIfAbsent(key, f) != null) { coalesced++; return inFlight.get(key).join(); }
        try { downstreamCalls++; String result = downstream.apply(key); f.complete(result); return result; }
        finally { inFlight.remove(key); }
    }
    int getDownstreamCalls() { return downstreamCalls; }
    int getCoalesced() { return coalesced; }
}

