class OptimizedGateway {
    private static final Logger log = Logger.getLogger("Overhead");
    private final ConnectionPool pool = new ConnectionPool(50);
    private final HybridRateLimiter limiter = new HybridRateLimiter(1000, 100);
    private final AsyncBatchLogger logger = new AsyncBatchLogger();
    private final RequestCoalescer coalescer = new RequestCoalescer();

    void handle(String accountId) {
        if (!limiter.allow()) return;      // local bucket, no Redis per request
        pool.acquire();                    // reuse upstream connection
        logger.log("served " + accountId); // async, off hot path
    }

    String coalescedLookup(String accountId) {
        return coalescer.lookup(accountId, key -> {
            slowDownstream();              // simulate one real backend call
            return key + "=Rs.1000000";
        });
    }

    private void slowDownstream() { try { Thread.sleep(30); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } }

    void report() {
        logger.shutdown();
        log.info(() -> String.format("Connection reuse = %.1f%% (new handshakes=%d)",
                pool.reusePercent(), pool.getNewHandshakes()));
        log.info(() -> "Redis syncs=" + limiter.getRedisSyncs() + " (vs per-request Redis calls avoided)");
        log.info(() -> "Coalescing: downstreamCalls=" + coalescer.getDownstreamCalls()
                + " coalesced=" + coalescer.getCoalesced() + " (50 identical → few real calls)");
    }
}

